 assert.deepEqual((await owner.query('SELECT * FROM shipit.cashbook_requests WHERE id=$1',[original.request.id])).rows[0],saved);assert.deepEqual((await owner.query('SELECT * FROM shipit.cashbook_effect_legs WHERE effect_id=$1',[original.effect.id])).rows,originalLegs);
 assert.deepEqual((await owner.query("SELECT source_kind,correction_of,direction,amount_paise::text amount FROM shipit.cashbook_source_facts WHERE source_id=$1",[correction.effect.id])).rows,[{source_kind:'correction',correction_of:original.request.id,direction:'out',amount:'20000'}]);
