 await owner.query("UPDATE shipit.attachments SET state='ready',scan_state='clean',actual_size=10,detected_type='image/png',digest=expected_digest,validated_at=clock_timestamp(),linked_at=clock_timestamp(),cleanup_due_at=NULL,version=version+1 WHERE id=$1",[id]);
